@@ -1678,4 +1678,82 @@ steps:
         let o: StepEnvironmentOverride = serde_yaml::from_str(yaml).unwrap();
         assert_eq!(o.command, Some("".to_string()));
     }
+
+    // --- Unknown field rejection tests ---
+
+    #[test]
+    fn rejects_unknown_top_level_field() {
+        let yaml = r#"
+app_name: "MyApp"
+unknown_field: "value"
+"#;
+        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
+        assert!(result.is_err(), "should reject unknown top-level field");
+        let err = result.unwrap_err().to_string();
+        assert!(
+            err.contains("unknown_field"),
+            "error should mention the unknown field name, got: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn rejects_unknown_settings_field() {
+        let yaml = r#"
+settings:
+  default_output: quiet
+  unkown_setting: true
+"#;
+        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
+        assert!(result.is_err(), "should reject unknown settings field");
+        let err = result.unwrap_err().to_string();
+        assert!(
+            err.contains("unkown_setting"),
+            "error should mention the unknown field name, got: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn rejects_unknown_step_field() {
+        let yaml = r#"
+steps:
+  test:
+    command: "echo test"
+    unkown_option: true
+"#;
+        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
+        assert!(result.is_err(), "should reject unknown step field");
+    }
+
+    #[test]
+    fn rejects_unknown_workflow_field() {
+        let yaml = r#"
+workflows:
+  default:
+    steps: [test]
+    unkown_option: true
+"#;
+        let result: Result<BivvyConfig, _> = serde_yaml::from_str(yaml);
+        assert!(result.is_err(), "should reject unknown workflow field");
+    }
+
+    #[test]
+    fn valid_config_with_all_known_fields_still_parses() {
+        let yaml = r#"
+app_name: "TestApp"
+settings:
+  default_output: quiet
+  logging: true
+steps:
+  test:
+    command: "echo test"
+    depends_on: []
+workflows:
+  default:
+    steps: [test]
+"#;
+        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
+        assert_eq!(config.app_name, Some("TestApp".to_string()));
+    }
 }
